"""Turn-scoped handle over a DialogueStateTracker.

``TrackerHandle`` is the single access point the SkillExecutor and Orchestrator
use to inspect and mutate conversation state. All state changes go through
``apply_events`` so that the tracker remains the source of truth and hooks
fire normally.
"""

from __future__ import annotations

from contextlib import contextmanager
from itertools import islice
from typing import TYPE_CHECKING, Any, Dict, Iterator, List, Optional, TypeGuard

import structlog
from pydantic import BaseModel, ConfigDict, Field

from rasa.dialogue_understanding.stack.dialogue_stack import (
    DialogueStack,  # (used in type hint string)
)
from rasa.dialogue_understanding.stack.frames.flow_stack_frame import (
    UserFlowStackFrame,
)
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.memory.manager import (
    ACTIVATE_TRIGGERS_FIRED_ENTRY,
    CORRECTION_RESUME_ENTRY,
    PENDING_TOOL_CONFIRMATION_ENTRY,
    WHEN_TRIGGER_MATCH_STATE_ENTRY,
)
from rasa.mantle.skills.catalog import target_id_for_frame
from rasa.mantle.skills.stack_frame_helpers import catalog_step_id_or_none
from rasa.mantle.state.pending_tool_confirmation import PendingToolConfirmation
from rasa.mantle.state.provenance import (
    WriteProvenance,
    attach_provenance,
)
from rasa.mantle.state.repair_metadata import (
    CorrectionMetadata,
    attach_correction_metadata,
)
from rasa.mantle.tools.tool_model_context import ToolModelContext
from rasa.shared.core.events import (
    Event,
    MemoryCleared,
    UserUttered,
    is_memory_write_event,
)
from rasa.shared.core.trackers import DialogueStateTracker

if TYPE_CHECKING:
    from rasa.mantle.memory.manager import MemoryManager
    from rasa.mantle.model_archive.bootstrap import ModelBootstrap


structlogger = structlog.get_logger()


def _is_skill_or_block_frame(
    frame: object,
) -> TypeGuard[SkillStackFrame | OrderedBlockStackFrame]:
    """Return whether *frame* is a skill or ordered-block stack frame."""
    return isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))


class _WriteContext(BaseModel):
    """The producing context active while a tool/setter writes memory.

    Set by :meth:`TrackerHandle.recording_write` around a builder-tool call so
    that every memory write the tool emits can be stamped with the producing
    tool name and arguments. Absent (``None``) for engine-internal writes
    (collect setters, ``set_memory`` steps), which are stamped with ``tool=None``.
    """

    model_config = ConfigDict(frozen=True)

    tool: Optional[str] = None
    arguments: Dict[str, Any] = Field(default_factory=dict)


class TrackerHandle:
    """Turn-scoped read/write wrapper over ``DialogueStateTracker``.

    The SkillExecutor and Orchestrator interact with tracker state exclusively
    through this class. Build one per turn via :func:`make_tracker_handle`, which
    is the only supported construction path and always wires a
    :class:`~rasa.mantle.memory.manager.MemoryManager`.
    """

    def __init__(self, tracker: DialogueStateTracker) -> None:
        self._tracker = tracker
        # Wired post-construction by make_tracker_handle() (two-phase: the
        # MemoryManager needs a reference to this handle). Do not construct
        # TrackerHandle directly — use the factory so memory is always present.
        self._memory_manager: Optional["MemoryManager"] = None
        # ENG-2950: Temporary ToolModelContext on every handle for
        # unsupported-request v1; replace with the proper tool contract.
        # https://rasahq.atlassian.net/browse/ENG-2950
        self._model_context: ToolModelContext = ToolModelContext()
        # Producing context for the write currently in flight, if any. Set by
        # recording_write() around builder-tool dispatch so emitted memory
        # writes carry write-provenance. None for engine-internal writes.
        self._active_write: Optional[_WriteContext] = None
        # Id of the LLM tool call currently being dispatched, if any. Set by
        # recording_tool_call() around dispatch_tool_call so every memory write
        # written during the dispatch (builder tools, set_fields, memory
        # validation tools) carries the exact join key to its ToolExecuted event.
        # Tracked independently of _active_write: set_fields writes without a
        # recording_write context but still belong to an LLM tool call.
        self._active_tool_call_id: Optional[str] = None
        # Depth counter for memory-validation-tool re-entrancy guard. While > 0,
        # memory writes from inside one must not trigger another.
        self._memory_validation_tools_depth: int = 0
        # Memory-validation ToolExecuted events queued during a set_fields or
        # correct dispatch so the orchestrator can flush them AFTER the parent
        # tool's own ToolExecuted.
        self._pending_memory_validation_events: List[Event] = []

    @property
    def model_context(self) -> ToolModelContext:
        """Read-only model-static data for in-process tools."""
        return self._model_context

    @property
    def memory(self) -> "MemoryManager":
        """Return the bound :class:`~rasa.mantle.memory.manager.MemoryManager`.

        Always present on handles built via :func:`make_tracker_handle`. Raises
        :exc:`RuntimeError` if the handle was constructed directly without
        wiring memory (an unsupported path).
        """
        if self._memory_manager is None:
            raise RuntimeError(
                "TrackerHandle has no MemoryManager. Build handles via "
                "make_tracker_handle(tracker, model_bootstrap) instead of "
                "constructing TrackerHandle directly."
            )
        return self._memory_manager

    @property
    def tracker(self) -> DialogueStateTracker:
        """Return the underlying tracker.

        Exposed so the orchestrator can build a fresh ``PromptContext`` on
        every iteration, guaranteeing the system prompt reflects the current
        stack and slot state.
        """
        return self._tracker

    # ------------------------------------------------------------------
    # Stack inspection
    # ------------------------------------------------------------------

    @property
    def stack(self) -> DialogueStack:
        """Return the current dialogue stack (live reference — read-only)."""
        return self._tracker.stack

    @property
    def active_frame(
        self,
    ) -> Optional[SkillStackFrame | OrderedBlockStackFrame | UserFlowStackFrame]:
        """Return the topmost skill, ordered-block, or user-flow frame, or ``None``."""
        top = self._tracker.stack.top()
        if isinstance(
            top, (SkillStackFrame, OrderedBlockStackFrame, UserFlowStackFrame)
        ):
            return top
        return None

    @property
    def active_flow_id(self) -> Optional[str]:
        """Return the compiled flow id of the currently active frame, or ``None``."""
        frame = self.active_frame
        if frame is None:
            return None
        if _is_skill_or_block_frame(frame):
            return target_id_for_frame(frame)
        return frame.flow_id if isinstance(frame, UserFlowStackFrame) else None

    def memory_scope(self) -> tuple[str, str]:
        """Return ``(skill_id, flow_id)`` scoping memory ops for the active frame.

        Resolves the owning skill from the topmost skill, ordered-block, or
        user-flow frame via
        :meth:`~rasa.mantle.memory.manager.MemoryManager.resolve_scope`.
        Returns ``("", "")`` when no such frame is active (routing mode).
        """
        frame = self.active_frame
        if frame is None:
            return "", ""
        return self.memory.resolve_scope(frame)

    @property
    def active_skill_id(self) -> Optional[str]:
        """Return the skill id stored on the currently active stack frame, or ``None``.

        Set whenever :meth:`SkillExecutor._activate` can resolve the
        owning skill — covers LLM ``activate`` calls, link steps, and
        call steps. Default-skill frames and any frame whose owning skill
        cannot be resolved carry ``None``.
        """
        frame = self.active_frame
        return frame.skill_id if frame else None

    @property
    def active_step_id(self) -> Optional[str]:
        """Return the persisted step id of the active frame, or ``None``.

        Ordered-block and user-flow frames store a step cursor. Skill frames
        do not; their prose step is not persisted on the stack.
        """
        frame = self.active_frame
        if frame is None or isinstance(frame, SkillStackFrame):
            return None
        return frame.step_id

    @property
    def stack_depth(self) -> int:
        """Return the number of frames currently on the dialogue stack."""
        return len(self._tracker.stack.frames)

    def skill_and_block_frames(self) -> List[SkillStackFrame | OrderedBlockStackFrame]:
        """Return skill and ordered-block frames on the stack (bottom to top)."""
        return [
            frame
            for frame in self._tracker.stack.frames
            if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))
        ]

    def user_flow_frames(self) -> List[UserFlowStackFrame]:
        """Return all ``UserFlowStackFrame`` entries on the stack (bottom to top)."""
        return [
            f for f in self._tracker.stack.frames if isinstance(f, UserFlowStackFrame)
        ]

    @property
    def current_user_message_timestamp(self) -> Optional[float]:
        """Return the timestamp of the turn's current user message, or ``None``.

        Reads the tracker's ``latest_message`` (the ``UserUttered`` that opened
        this turn), falling back to a scan of the event log for the most recent
        ``UserUttered`` when the tracker exposes no parsed ``latest_message``
        (e.g. minimal test trackers). Returns ``None`` when the conversation has
        no user message yet.

        The timestamp is a float carrying no PII, unlike the message text. It
        lets the Inspector resolve the triggering message by matching against
        the ``UserUttered`` on the tracker rather than duplicating the text.
        """
        latest_message = getattr(self._tracker, "latest_message", None)
        if latest_message is not None:
            timestamp = getattr(latest_message, "timestamp", None)
            if timestamp is not None:
                return timestamp
        for event in reversed(list(getattr(self._tracker, "events", ()) or ())):
            if isinstance(event, UserUttered):
                return event.timestamp
        return None

    # ------------------------------------------------------------------
    # Slot inspection
    # ------------------------------------------------------------------

    def get_slot(self, name: str) -> Any:
        """Return the current value of a tracker slot (``None`` if unset)."""
        return self._tracker.get_slot(name)

    # ------------------------------------------------------------------
    # Event application
    # ------------------------------------------------------------------

    def create_stack_update_events(self, new_stack: "DialogueStack") -> List[Event]:
        """Return ``DialogueStackUpdated`` events needed to transition to *new_stack*.

        Uses the tracker's own patch mechanism so the update is minimal and
        correct. Returns an empty list when *new_stack* equals the current
        stack (no-op).
        """
        return self._tracker.create_stack_updated_events(new_stack)

    def apply_events(self, events: List[Event]) -> None:
        """Append *events* to the tracker and log for observability.

        This is the **only** way the engine should mutate tracker state —
        never call ``tracker.update`` directly from SkillExecutor code.

        Every memory write is stamped with write-provenance (producing tool/step/
        frame, arguments, and a monotonic position) so cross-phase corrections
        can later re-invoke producers and clear values written after a rewind
        point. Events that already carry provenance are left untouched.
        """
        if not events:
            return

        self._stamp_write_provenance(events)

        structlogger.debug(
            "mantle.tracker_handle.apply_events",
            event_count=len(events),
            event_types=[type(e).__name__ for e in events],
        )
        self._tracker.update_with_events(events)

    def queue_memory_validation_events(self, events: List[Event]) -> None:
        """Buffer memory-validation ToolExecuted events for deferred application.

        Called by :func:`~rasa.mantle.orchestration.settable_write.write_settable_field`
        instead of applying the events immediately, so the orchestrator can
        flush them after the parent tool's own ToolExecuted.
        """
        self._pending_memory_validation_events.extend(events)

    def drain_memory_validation_events(self) -> List[Event]:
        """Return and clear queued memory-validation ToolExecuted events.

        The orchestrator calls this after each tool's ToolExecuted so these
        rows follow the parent tool on the tracker.
        """
        events = list(self._pending_memory_validation_events)
        self._pending_memory_validation_events.clear()
        return events

    @property
    def correction_resume_point(self) -> Optional[Dict[str, str]]:
        """Return the pending correction's resume point, or ``None``.

        A ``{"frame_id", "step_id"}`` mapping recording where the flow was when
        the user revised a value — the step the post-correction re-walk must
        reach before it is considered caught up. Held as a reserved (engine
        ``system.*``) memory item so it survives across turns while the re-walk
        re-asks cleared values.

        Read on the hot prompt path every turn, so it degrades gracefully to
        ``None`` when no :class:`MemoryManager` is wired (e.g. a bare handle in
        a unit test) rather than raising — there is no correction to resume.
        """
        if self._memory_manager is None:
            return None
        value = self.memory.get_system(CORRECTION_RESUME_ENTRY)
        return value if isinstance(value, dict) else None

    @property
    def memory_validation_tools_suppressed(self) -> bool:
        """Return ``True`` while a memory validation tool is running."""
        return self._memory_validation_tools_depth > 0

    @contextmanager
    def suppress_memory_validation_tools(self) -> Iterator[None]:
        """Prevent nested memory validation tools while one is executing.

        A ``run_after_setting_<entry>`` tool may itself write memory (e.g. derive
        and set a second field). Without this guard that inner write would
        trigger *its own* memory validation tool, which could write again — an
        unbounded recursion, or at least a surprising cascade the author never
        opted into. The write path (``write_settable_field``) checks
        :attr:`memory_validation_tools_suppressed` and runs these tools only for
        top-level writes; this context manager brackets a tool's execution so
        every write made inside it is treated as nested and skips further tools.
        """
        self._memory_validation_tools_depth += 1
        try:
            yield
        finally:
            self._memory_validation_tools_depth -= 1

    @property
    def correction_in_progress(self) -> bool:
        """Whether a correction re-walk is still catching up to its trigger step.

        Read when building the prompt: while ``True`` the LLM is told that a
        correction cleared captured memory (re-set safe values from history,
        re-ask any that depend on the corrected one).
        """
        return self.correction_resume_point is not None

    def set_correction_resume_point(self, frame_id: str, step_id: str) -> None:
        """Record where a correction re-walk must return to before it clears.

        Called by the replay drivers after they rewind a frame and clear the
        now-stale downstream memory, capturing the step the flow was on when the
        user made the correction. The marker persists (a reserved ``system.*``
        memory item) until :meth:`clear_correction_resume_point` drops it once
        the re-walk reaches that step.
        """
        self.memory.set_system(
            CORRECTION_RESUME_ENTRY, {"frame_id": frame_id, "step_id": step_id}
        )

    def clear_correction_resume_point(self) -> None:
        """Drop the pending correction resume point once the re-walk caught up."""
        self.memory.set_system(CORRECTION_RESUME_ENTRY, None)

    @property
    def pending_tool_confirmation(self) -> Optional[PendingToolConfirmation]:
        """Return the stored pending confirmation payload, or ``None``.

        Held as ``system.pending_tool_confirmation`` so it survives across turns
        while the confirmation ask is outstanding. Degrades to ``None`` when no
        :class:`MemoryManager` is wired (bare unit-test handles).

        Prefer :meth:`pending_tool_confirmation_for_active_frame` at runtime so
        digressed or completed tasks do not surface another frame's pending ask.
        """
        if self._memory_manager is None:
            return None
        value = self.memory.get_system(PENDING_TOOL_CONFIRMATION_ENTRY)
        if not isinstance(value, dict):
            return None
        try:
            return PendingToolConfirmation.model_validate(value)
        except ValueError:
            structlogger.warning(
                "mantle.tracker_handle.pending_tool_confirmation.invalid",
            )
            return None

    def pending_tool_confirmation_for_active_frame(
        self,
    ) -> Optional[PendingToolConfirmation]:
        """Return pending confirmation only when it belongs to the active frame.

        Matches on ``skill_id`` and, when recorded, ``frame_id`` so a paused
        ``requires_confirmation`` gate does not leak into digressed or resumed tasks.
        """
        pending = self.pending_tool_confirmation
        if pending is None:
            return None
        frame = self.active_frame
        if frame is None:
            return None
        active_skill_id, _ = self.memory_scope()
        if pending.skill_id != active_skill_id:
            return None
        if pending.frame_id is not None and pending.frame_id != frame.frame_id:
            return None
        return pending

    def set_pending_tool_confirmation(
        self, pending_tool_confirmation: PendingToolConfirmation
    ) -> None:
        """Persist a tool call that must not run until the user confirms."""
        self.memory.set_system(
            PENDING_TOOL_CONFIRMATION_ENTRY,
            pending_tool_confirmation.model_dump(mode="json"),
        )

    def clear_pending_tool_confirmation(self) -> None:
        """Drop a pending tool confirmation after dispatch or cancel."""
        self.memory.set_system(PENDING_TOOL_CONFIRMATION_ENTRY, None)

    def clear_pending_tool_confirmation_if_owned_by(
        self, *, frame_id: Optional[str], skill_id: Optional[str]
    ) -> None:
        """Drop pending confirmation when the owning frame is abandoned."""
        pending = self.pending_tool_confirmation
        if pending is None:
            return
        if not pending.is_owned_by(frame_id=frame_id, skill_id=skill_id):
            return
        self.clear_pending_tool_confirmation()
        structlogger.info(
            "mantle.tracker_handle.pending_tool_confirmation.cleared",
            reason="owning_frame_abandoned",
            tool_name=pending.tool_name,
        )

    def activate_trigger_already_fired(self, frame_id: str, response_name: str) -> bool:
        """Return whether *response_name* already fired on stack frame *frame_id*."""
        raw = self.memory.get_system(ACTIVATE_TRIGGERS_FIRED_ENTRY)
        if not isinstance(raw, dict):
            return False
        fired = raw.get(frame_id)
        if not isinstance(fired, list):
            return False
        return response_name in fired

    def mark_activate_trigger_fired(self, frame_id: str, response_name: str) -> None:
        """Record *response_name* as fired for ``on: activate`` on *frame_id*."""
        raw = self.memory.get_system(ACTIVATE_TRIGGERS_FIRED_ENTRY)
        fired_by_frame: dict[str, list[str]] = (
            dict(raw) if isinstance(raw, dict) else {}
        )
        fired = list(fired_by_frame.get(frame_id, []))
        if response_name not in fired:
            fired.append(response_name)
        fired_by_frame[frame_id] = fired
        self.memory.set_system(ACTIVATE_TRIGGERS_FIRED_ENTRY, fired_by_frame)

    def when_trigger_matched_before(self, frame_id: str, response_name: str) -> bool:
        """Return whether *response_name* matched on the previous when evaluation."""
        raw = self.memory.get_system(WHEN_TRIGGER_MATCH_STATE_ENTRY)
        if not isinstance(raw, dict):
            return False
        frame_state = raw.get(frame_id)
        if not isinstance(frame_state, dict):
            return False
        return bool(frame_state.get(response_name, False))

    def record_when_trigger_match(
        self, frame_id: str, response_name: str, matches: bool
    ) -> None:
        """Record the latest ``when:`` match state for *response_name* on *frame_id*."""
        raw = self.memory.get_system(WHEN_TRIGGER_MATCH_STATE_ENTRY)
        state_by_frame: dict[str, dict[str, bool]] = (
            dict(raw) if isinstance(raw, dict) else {}
        )
        frame_state = dict(state_by_frame.get(frame_id, {}))
        frame_state[response_name] = matches
        state_by_frame[frame_id] = frame_state
        self.memory.set_system(WHEN_TRIGGER_MATCH_STATE_ENTRY, state_by_frame)

    @contextmanager
    def recording_write(
        self, *, tool: Optional[str], arguments: Optional[Dict[str, Any]] = None
    ) -> Iterator[None]:
        """Mark the producing context for memory writes inside the block.

        Builder-tool dispatch wraps the tool invocation in this context so that
        every memory write the tool emits via :meth:`apply_events` is stamped
        with *tool* and *arguments*. Nested contexts are restored on exit, so a
        tool that triggers further writes keeps the outermost producing context.

        Args:
            tool: Name of the producing builder tool, or ``None`` to mark an
                engine-internal write.
            arguments: Arguments the producer was called with.
        """
        previous = self._active_write
        self._active_write = _WriteContext(tool=tool, arguments=dict(arguments or {}))
        try:
            yield
        finally:
            self._active_write = previous

    @contextmanager
    def recording_tool_call(self, tool_call_id: str) -> Iterator[None]:
        """Mark the LLM tool call being dispatched for writes inside the block.

        ``dispatch_tool_call`` wraps a dispatch that originates from an LLM
        tool call in this context so every memory write applied during the
        dispatch — builder-tool writes, ``set_fields`` direct writes, and
        memory-validation-tool writes — is stamped with *tool_call_id*, the exact
        join key to the ``ToolExecuted`` event's ``tool_call_id``
        metadata. Tracked independently of :meth:`recording_write` so writes
        without a producing-tool context still carry the id. Nested contexts
        are restored on exit, mirroring :meth:`recording_write`.

        Args:
            tool_call_id: Id of the dispatching LLM tool call.
        """
        previous = self._active_tool_call_id
        self._active_tool_call_id = tool_call_id
        try:
            yield
        finally:
            self._active_tool_call_id = previous

    @contextmanager
    def recording_correction(
        self, *, memory_key: str, correction: CorrectionMetadata
    ) -> Iterator[None]:
        """Stamp correction metadata after a successful apply in the block.

        ``CorrectionExecutor`` wraps the apply step. On exit, if *memory_key*
        still differs from its value at enter, the last memory write for that
        key (written inside the block) that established the final value is
        tagged. Intermediate or reverted writes leave no stamp — matching the
        executor's "skip replay when memory is unchanged" rule so eval reports
        do not show false ``- correction`` lines.

        Args:
            memory_key: Slot key whose applying write should be tagged.
            correction: Trigger-frame ids for the successful ``correct()``.
        """
        value_at_enter = self.get_slot(memory_key)
        event_count_at_enter = len(getattr(self._tracker, "events", ()) or ())
        try:
            yield
        finally:
            self._stamp_successful_correction(
                memory_key=memory_key,
                correction=correction,
                value_at_enter=value_at_enter,
                event_count_at_enter=event_count_at_enter,
            )

    def _stamp_write_provenance(self, events: List[Event]) -> None:
        """Stamp provenance onto every un-stamped memory-write event in *events*.

        Applies to ``SlotSet``, ``MemorySet``, and ``MemoryCleared``. ``position``
        aligns with tracker event order: it is the index the event will occupy
        once appended, so positions are monotonic across the conversation and
        stable once persisted in the event metadata. The event count is read
        defensively so handles wrapping minimal test trackers (without an
        ``events`` log) still apply writes without provenance noise.
        """
        if not any(is_memory_write_event(event) for event in events):
            return
        base_position = len(getattr(self._tracker, "events", ()) or ())
        context = self._active_write
        active_frame = self.active_frame
        frame_id = active_frame.frame_id if active_frame is not None else None
        step_id = catalog_step_id_or_none(active_frame)
        skill_id = self._active_scope_skill_id(active_frame)
        for offset, event in enumerate(events):
            if not is_memory_write_event(event):
                continue
            attach_provenance(
                event,
                WriteProvenance(
                    tool=context.tool if context is not None else None,
                    skill_id=skill_id,
                    step=step_id,
                    frame_id=frame_id,
                    arguments=dict(context.arguments) if context is not None else {},
                    position=base_position + offset,
                    tool_call_id=self._active_tool_call_id,
                ),
            )

    def _active_scope_skill_id(
        self, active_frame: Optional[UserFlowStackFrame]
    ) -> Optional[str]:
        """Return the owning skill id for *active_frame*'s memory scope, or ``None``.

        Mirrors :meth:`memory_scope`'s skill resolution (frame skill id, else the
        catalog owner of its flow) so the stamped ``skill_id`` agrees with the
        scope the write actually targeted. ``None`` while routing (no frame) or
        when no memory manager is wired (bare test handles).
        """
        if active_frame is None or self._memory_manager is None:
            return None
        skill_id, _flow_id = self.memory.resolve_scope(active_frame)
        return skill_id or None

    def _stamp_successful_correction(
        self,
        *,
        memory_key: str,
        correction: CorrectionMetadata,
        value_at_enter: Any,
        event_count_at_enter: int,
    ) -> None:
        """Tag the applying memory write only when the correction stuck.

        No-op when the slot value matches *value_at_enter* (rejected, same-value,
        or write-then-revert). Otherwise stamps the last memory write for
        *memory_key* written after *event_count_at_enter* whose value equals the
        current slot value.
        """
        current_value = self.get_slot(memory_key)
        if current_value == value_at_enter:
            return

        last_applying = None
        # ``DialogueStateTracker.events`` is a ``deque`` (no slice support).
        # ``islice`` walks the tail without copying the full history.
        events = getattr(self._tracker, "events", ()) or ()
        for event in islice(events, event_count_at_enter, None):
            if not is_memory_write_event(event) or event.key != memory_key:
                continue
            written = None if isinstance(event, MemoryCleared) else event.value
            if written != current_value:
                continue
            last_applying = event

        if last_applying is not None:
            attach_correction_metadata(last_applying, correction)


def make_tracker_handle(
    tracker: DialogueStateTracker,
    model_bootstrap: "ModelBootstrap",
) -> TrackerHandle:
    """Build a ``TrackerHandle`` from a ``DialogueStateTracker``.

    The handle always receives a bound
    :class:`~rasa.mantle.memory.manager.MemoryManager` constructed from the
    bootstrap's ``skill_catalog`` and ``project_memory``. This is the only
    supported way to build a ``TrackerHandle``.

    Args:
        tracker: The live dialogue state tracker for this turn.
        model_bootstrap: Loaded model metadata. Used to wire a
        :class:`~rasa.mantle.memory.manager.MemoryManager` and
        :class:`~rasa.mantle.tools.tool_model_context.ToolModelContext`
        on the handle.

    Returns:
        A :class:`TrackerHandle` wrapping *tracker* with memory wired.
    """
    from rasa.mantle.memory.manager import MemoryManager

    # Two-phase construction: build the handle first so the MemoryManager can
    # call handle.apply_events() for writes, preserving the single mutation path.
    handle = TrackerHandle(tracker)
    memory_manager = MemoryManager(
        skill_catalog=model_bootstrap.skill_catalog,
        project_memory=model_bootstrap.project_memory,
        handle=handle,
    )
    handle._memory_manager = memory_manager
    handle._model_context = ToolModelContext.from_bootstrap(model_bootstrap)
    return handle
